<template><div class="page-card"><div class="toolbar"><el-button @click="load">刷新</el-button></div><el-table :data="rows"><el-table-column label="时间" width="190"><template #default="s">{{ $dt(s.row.created_at) }}</template></el-table-column><el-table-column prop="user_name" label="用户" width="120"/><el-table-column prop="operation_type" label="操作" width="150"/><el-table-column prop="resource_type" label="资源" width="120"/><el-table-column prop="resource_id" label="资源ID" width="100"/><el-table-column prop="request_method" label="方法" width="80"/><el-table-column prop="request_path" label="路径" min-width="220"/><el-table-column prop="ip_address" label="IP" width="150"/><el-table-column prop="status" label="状态" width="100"/></el-table><div style="display:flex;justify-content:flex-end;margin-top:16px"><el-pagination v-model:current-page="page" :total="total" :page-size="30" @current-change="load"/></div></div></template>
<script setup>import { onMounted, ref } from 'vue';import api from '../api';const rows=ref([]),total=ref(0),page=ref(1);async function load(){const{data}=await api.get('/operations',{params:{page:page.value,page_size:30}});rows.value=data.items;total.value=data.total}onMounted(load)</script>
